import{_ as a,o as e,a as r,b as i}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/README.md","filePath":"api/SIMD-API/c_api/README.md","outlineHeaders":[{"level":2,"title":"定位与特性","slug":"定位与特性","link":"#定位与特性"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件","link":"#需要包含的头文件"},{"level":2,"title":"API类型介绍","slug":"API类型介绍","link":"#API类型介绍"},{"level":2,"title":"关键字","slug":"关键字","link":"#关键字"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":2,"title":"参考样例","slug":"参考样例","link":"#参考样例"}],"lastUpdated":1787832553000}'),l={name:"api/SIMD-API/c_api/README.md"};function d(h,t,A,E,s,c){return e(),r("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>C API</h1><p>C API开放芯片完备编程能力，支持<a href="general_description_and_constraints.html#%E4%BB%A5%E6%95%B0%E7%BB%84%E6%96%B9%E5%BC%8F%E7%94%B3%E8%AF%B7%E5%86%85%E5%AD%98">以数组形式分配内存</a>，一般基于指针编程。提供与业界一致的C语言编程体验。</p><h2 id="定位与特性">定位与特性<a class="header-anchor" href="#定位与特性">​</a></h2><p>C API是Ascend C三层梯度化编程接口中的<strong>语言扩展层SIMD API</strong>，定位为最底层的C语言接口，基于指针编程，提供完备的C语言编程能力。C API可直接映射NPU硬件指令，开发者自主管理内存搬运与同步（与TPipe/TQue自动管理内存、同步不同），开放全部底层硬件能力。适配C语言开发习惯，适合对性能和可控性要求较高的算子开发场景，是追求极致性能、充分释放NPU硬件潜能的核心路径。</p><p>详细内容请参考<a href="../../../guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/c_programming_overview.html">C语言编程概述</a>。</p><h2 id="需要包含的头文件">需要包含的头文件<a class="header-anchor" href="#需要包含的头文件">​</a></h2><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>包含asc_simd.h文件来调用C API相应接口。如无特殊说明，包含该头文件即可满足接口调用需求。 若API文档中有特殊说明，则应遵循API的具体说明。</p></div><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>
</code></pre></div><h2 id="API类型介绍">API类型介绍<a class="header-anchor" href="#API类型介绍">​</a></h2><ul><li>前n个数据计算：该类型API在计算时采用“紧密排布”的数据读取方式，即从起始位置开始，按顺序连续获取所需数据。例如，若需处理N个数据，则从源操作数的第0个位置开始，依次取至第N-1个位置。</li><li>高维切分计算：该类型API按照设定的规则“跳过部分数据”。适合处理需要间隔采样的场景，灵活度高，但需要额外配置相关参数。</li><li>同步计算：该类型API内部自动插入同步操作，易用性更强。</li></ul><h2 id="关键字">关键字<a class="header-anchor" href="#关键字">​</a></h2><p><strong>表1</strong> 关键字列表</p><table><thead><tr><th>名称</th><th>描述</th></tr></thead><tbody><tr><td>__gm__</td><td>存储空间定义修饰符，表示被修饰的变量位于Global Memory地址空间。</td></tr><tr><td>__ubuf__</td><td>存储空间定义修饰符，表示被修饰的变量位于UB地址空间。</td></tr><tr><td>__aicore__</td><td>执行空间限定符。表示该函数只能在Ai Core上执行。</td></tr><tr><td>__cbuf__</td><td>存储空间定义修饰符，表示被修饰的变量位于L1 Buffer地址空间。</td></tr><tr><td>__simd_callee__</td><td>执行空间限定符。表示该函数只能在Reg上执行。</td></tr></tbody></table><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>NPU内部有不同的计算单元，在计算时往往需要把计算数据搬运到计算单元上。不同计算单元上的计算过程、数据搬运过程可划分为不同的流水线。在AI Core上执行的操作会被分配到不同的流水线(PIPE)上执行，包括以下几种：</p><ul><li>PIPE_S：标量流水线，负责指令分发和标量计算。</li><li>PIPE_V：矢量计算流水线。</li><li>PIPE_M：矩阵计算流水线。</li><li>PIPE_MTE1：搬运操作。包括从L1 Buffer到L0A Buffer或L0B Buffer，从L1 Buffer到Unified Buffer（UB）的搬运操作和L0A Buffer或L0B Buffer的初始化操作。</li><li>PIPE_MTE2：搬运操作。包括从GM到L1 Buffer、从GM到L0A Buffer或L0B Buffer、从GM到UB的搬运操作和L1 Buffer的初始化操作。</li><li>PIPE_MTE3：搬运操作。包括从UB到GM、从UB到L1 Buffer、从L1 Buffer到GM的操作和从UB到UB的搬运操作。</li><li>PIPE_FIX：Fixpipe流水线。</li><li>PIPE_ALL：所有流水线。</li></ul><p>可通过<a href="sync/sync.html">同步控制</a>类API控制同一流水线内的运行顺序和不同流水线间的执行顺序。</p><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><table><thead><tr><th>目录</th></tr></thead><tbody><tr><td><a href="c_api.html#%E5%9F%BA%E7%A1%80%E5%AE%9A%E4%B9%89">基础定义</a></td></tr><tr><td><a href="c_api.html#%E5%B7%A5%E5%85%B7%E6%8E%A5%E5%8F%A3">工具接口</a></td></tr><tr><td><a href="c_api.html#%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97">矩阵计算</a></td></tr><tr><td><a href="c_api.html#%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97%E6%90%AC%E8%BF%90">矩阵计算搬运</a></td></tr><tr><td><a href="c_api.html#memory%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97">Memory矢量计算</a></td></tr><tr><td><a href="c_api.html#%E7%9F%A2%E9%87%8F%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90">矢量数据搬运</a></td></tr><tr><td><a href="c_api.html#reg%E7%9F%A2%E9%87%8F%E8%AE%A1%E7%AE%97">Reg矢量计算</a></td></tr><tr><td><a href="c_api.html#%E6%A0%87%E9%87%8F%E8%AE%A1%E7%AE%97">标量计算</a></td></tr><tr><td><a href="c_api.html#%E5%8E%9F%E5%AD%90%E6%93%8D%E4%BD%9C">原子操作</a></td></tr><tr><td><a href="c_api.html#%E7%BC%93%E5%AD%98%E6%8E%A7%E5%88%B6">缓存控制</a></td></tr><tr><td><a href="c_api.html#%E5%90%8C%E6%AD%A5%E6%8E%A7%E5%88%B6">同步控制</a></td></tr><tr><td><a href="c_api.html#%E5%85%B6%E4%BB%96%E6%93%8D%E4%BD%9C">其他操作</a></td></tr><tr><td><a href="c_api.html#%E7%89%B9%E6%AE%8A%E5%AF%84%E5%AD%98%E5%99%A8%E8%AE%BF%E9%97%AE">特殊寄存器访问</a></td></tr><tr><td><a href="deprecated_interface/deprecated_interface.html">废弃接口</a></td></tr></tbody></table><h2 id="参考样例">参考样例<a class="header-anchor" href="#参考样例">​</a></h2><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品的C API样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/02_simd_c_api/00_introduction/01_add">C API Add样例</a>。 Ascend 950PR/Ascend 950DT的C API样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/02_simd_c_api/00_introduction/04_reg_base_add_compute">C API Add样例</a>。</p></article></div>`,1)])])}const n=a(l,[["render",d]]);export{p as __pageData,n as default};
